-- The hiring tracker template, as Postgres tables. Made by baseToSql (@svgrid/enterprise/base);
-- the svgrid: comments keep what SQL has no type for, so baseFromDatabase opens it as the same base.

create table "candidates" (
  "id" text primary key default gen_random_uuid()::text,
  "svgrid_order" bigint generated always as identity,
  "name" text,
  "photo" jsonb,
  "role_id" text,
  "stage" text,
  "recruiter" text,
  "rating" double precision,
  "interview" date,
  "salary" double precision,
  "email" text,
  "resume" jsonb,
  "source" text,
  "notes" text
);
create table "roles" (
  "id" text primary key default gen_random_uuid()::text,
  "svgrid_order" bigint generated always as identity,
  "name" text,
  "team" text,
  "manager" text,
  "headcount" double precision,
  "status" text
);

comment on column "candidates"."name" is 'svgrid:{"field":"name","header":"Candidate","width":200,"fieldType":"text"}';
comment on column "candidates"."photo" is 'svgrid:{"field":"photo","header":"Photo","width":90,"fieldType":"attachment","fieldProps":{"accept":"image/*","maxFiles":1}}';
comment on column "candidates"."role_id" is 'svgrid:{"field":"role","header":"Role","width":180,"fieldType":"link","fieldProps":{"table":"roles","multiple":false,"inverse":"candidates"}}';
comment on column "candidates"."stage" is 'svgrid:{"field":"stage","header":"Stage","width":140,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Applied","color":"#94a3b8"},{"value":"Phone screen","color":"#18bfff"},{"value":"Onsite","color":"#2d7ff9"},{"value":"Offer","color":"#fcb400"},{"value":"Hired","color":"#20c933"},{"value":"Rejected","color":"#f82b60"}]}}';
comment on column "candidates"."recruiter" is 'svgrid:{"field":"recruiter","header":"Recruiter","width":160,"fieldType":"user"}';
comment on column "candidates"."rating" is 'svgrid:{"field":"rating","header":"Rating","width":130,"fieldType":"rating","fieldProps":{"max":5,"color":"#fcb400"}}';
comment on column "candidates"."interview" is 'svgrid:{"field":"interview","header":"Interview","width":150,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on column "candidates"."salary" is 'svgrid:{"field":"salary","header":"Salary ask","width":130,"fieldType":"number","fieldProps":{"format":"currency","symbol":"$","precision":0,"summary":"avg"}}';
comment on column "candidates"."email" is 'svgrid:{"field":"email","header":"Email","width":220,"fieldType":"email"}';
comment on column "candidates"."resume" is 'svgrid:{"field":"resume","header":"Resume","width":200,"fieldType":"attachment"}';
comment on column "candidates"."source" is 'svgrid:{"field":"source","header":"Source","width":130,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Referral","color":"#8b46ff"},{"value":"Careers page","color":"#2d7ff9"},{"value":"LinkedIn","color":"#18bfff"},{"value":"Agency","color":"#ff6f2c"}]}}';
comment on column "candidates"."notes" is 'svgrid:{"field":"notes","header":"Notes","width":260,"fieldType":"longText"}';
comment on table "candidates" is 'svgrid:{"v":1,"name":"Candidates","position":0,"primaryField":"name","order":["name","photo","role","stage","recruiter","rating","interview","salary","email","resume","source","notes"],"extra":[],"views":[{"id":"pipeline","name":"Hiring pipeline","type":"kanban","stackBy":"stage","color":{"mode":"none"},"state":{"sorting":[],"grouping":[],"columnWidths":{"name":200,"photo":90,"role":180,"stage":140,"recruiter":160,"rating":130,"interview":150,"salary":130,"email":220,"resume":200,"source":130,"notes":260},"columnPinning":{"left":["name"],"right":[]},"columnOrder":["name","photo","role","stage","recruiter","rating","interview","salary","email","resume","source","notes"],"hiddenColumns":[],"globalFilter":"","columnFilters":{},"facetFilters":{}},"rowHeight":44},{"id":"all","name":"All candidates","type":"grid","color":{"mode":"field","field":"stage"},"state":{"sorting":[{"id":"rating","desc":true}]}},{"id":"faces","name":"Faces","type":"gallery","coverField":"photo"},{"id":"interviews","name":"Interviews","type":"calendar","dateField":"interview","color":{"mode":"field","field":"stage"}},{"id":"funnel","name":"Candidates by stage","type":"chart","chart":{"kind":"donut","x":"stage"}},{"id":"apply","name":"Apply","type":"form","formFields":["name","email","role","resume","notes"],"formTitle":"Join the team","formDescription":"Tell us a little about yourself. We reply to every application within a week."}]}';
comment on column "roles"."name" is 'svgrid:{"field":"name","header":"Role","width":200,"fieldType":"text"}';
comment on column "roles"."team" is 'svgrid:{"field":"team","header":"Team","width":140,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Engineering","color":"#2d7ff9"},{"value":"Design","color":"#ff08c2"},{"value":"Data","color":"#20c933"},{"value":"Support","color":"#ff6f2c"}]}}';
comment on column "roles"."manager" is 'svgrid:{"field":"manager","header":"Hiring manager","width":190,"fieldType":"user"}';
comment on column "roles"."headcount" is 'svgrid:{"field":"headcount","header":"Headcount","width":132,"fieldType":"number","fieldProps":{"format":"integer","summary":"sum"}}';
comment on column "roles"."status" is 'svgrid:{"field":"status","header":"Status","width":120,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Open","color":"#20c933"},{"value":"On hold","color":"#fcb400"},{"value":"Filled","color":"#94a3b8"}]}}';
comment on table "roles" is 'svgrid:{"v":1,"name":"Roles","position":1,"primaryField":"name","order":["name","team","manager","headcount","status","candidates","candidateCount"],"extra":[{"field":"candidates","header":"Candidates","width":320,"fieldType":"link","fieldProps":{"table":"candidates","multiple":true,"inverse":"role"}},{"field":"candidateCount","header":"In the pipeline","width":140,"fieldType":"count","fieldProps":{"linkField":"candidates"}}],"views":[{"id":"roles","name":"Open roles","type":"grid","color":{"mode":"field","field":"team"}},{"id":"by-team","name":"By team","type":"kanban","stackBy":"team"}]}';

